 964	    fn left_pane_click_target(&mut self, row: u16) -> Option<LeftPaneClickTarget> {
 965	        let list_row = usize::from(row.saturating_sub(2));
 966	        if row < 2 {
 967	            return None;
 968	        }
 969	        if list_row == 0 {
 970	            self.control_selected = 0;
 971	            return Some(LeftPaneClickTarget::Command);
 972	        }
 973	
 974	        let mut current_row = 1;
 975	        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
 976	            let agent = &self.agents[*agent_index];
 977	            if list_row == current_row {
 978	                self.control_selected = visible_position + 1;
 979	                return Some(LeftPaneClickTarget::Agent(agent.id.clone()));
 980	            }
 981	            current_row += 1;
 982	
 983	            if !agent.modified_files.is_empty() {
 984	                if list_row == current_row {
 985	                    self.control_selected = visible_position + 1;
 986	                    return Some(LeftPaneClickTarget::Agent(agent.id.clone()));
 987	                }
 988	                current_row += 1;
 989	            }
 990	
 991	            for linked_agents in [
 992	                &agent.conflicting_agents,
 993	                &agent.depends_on,
 994	                &agent.depended_on_by,
 995	            ] {
 996	                if !linked_agents.is_empty() {
 997	                    if list_row == current_row {
 998	                        self.control_selected = visible_position + 1;
 999	                        return linked_agents
1000	                            .first()
1001	                            .cloned()
1002	                            .map(LeftPaneClickTarget::Agent);
1003	                    }
1004	                    current_row += 1;
1005	                }
1006	            }
1007	        }
1008	
1009	        None
1010	    }
