fn left_widget(&self) -> List<'static> {
    let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
    let items = self
        .left_display_lines(inner_width)
        .into_iter()
        .enumerate()
        .map(|(row, line)| {
            let item = ListItem::new(self.styled_pane_line(
                PaneFocus::Left,
                row,
                &line.text,
                Style::default(),
            ));
            if line.ready {
                item.style(Style::default().add_modifier(Modifier::REVERSED))
            } else {
                item
            }
        })
        .collect::<Vec<_>>();
    List::new(items).block(Block::default().title("work-leaf").borders(Borders::ALL))
}

fn left_display_lines(&self, inner_width: usize) -> Vec<LeftDisplayLine> {
    let mut lines = vec![LeftDisplayLine {
        text: if self.control_selected == 0 {
            "> work-leaf  command".to_string()
        } else {
            "  work-leaf  command".to_string()
        },
        ready: false,
    }];
    for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
        let agent = &self.agents[*agent_index];
        let selected = self.control_selected == visible_position + 1;
        lines.push(LeftDisplayLine {
            text: compact_agent_row(agent, selected, inner_width),
            ready: agent.ready,
        });
        if !agent.modified_files.is_empty() {
            lines.push(LeftDisplayLine {
                text: format!(
                    "    files: {}",
                    agent
                        .modified_files
                        .iter()
                        .map(|path| path.display().to_string())
                        .collect::<Vec<_>>()
                        .join(", ")
                ),
                ready: false,
            });
        }
        for (label, agents) in [
            ("conflicts", &agent.conflicting_agents),
            ("depends-on", &agent.depends_on),
            ("depended-on-by", &agent.depended_on_by),
        ] {
            if !agents.is_empty() {
                lines.push(LeftDisplayLine {
                    text: format!(
                        "    {label}: {}",
                        agents
                            .iter()
                            .map(AgentId::as_str)
                            .collect::<Vec<_>>()
                            .join(", ")
                    ),
                    ready: false,
                });
            }
        }
    }
    lines
}

fn right_widget(&self, right_content: &str) -> Paragraph<'static> {
    let title = match self.windows[self.active_window].surface {
        UiSurface::WorkLeafCommand => "command",
        UiSurface::AgentChat => "chat",
    };
    let rows = split_preserving_empty_lines(right_content)
        .into_iter()
        .enumerate()
        .map(|(row, line)| self.styled_pane_line(PaneFocus::Right, row, line, Style::default()))
        .collect::<Vec<_>>();
    Paragraph::new(rows)
        .block(Block::default().title(title).borders(Borders::ALL))
        .wrap(Wrap { trim: false })
}

fn styled_pane_line(
    &self,
    pane: PaneFocus,
    row: usize,
    line: &str,
    base_style: Style,
) -> Spans<'static> {
    let selection_range = self.selection_range_for_line(pane, row, line);
    Spans::from(styled_line_spans(line, selection_range, base_style))
}

fn selection_range_for_line(
    &self,
    pane: PaneFocus,
    row: usize,
    line: &str,
) -> Option<(usize, usize)> {
    let selection = self.visual_selection.as_ref()?;
    if selection.pane != pane {
        return None;
    }
    visual_range_for_row(selection, row, line.chars().count())
}

fn prepare_visual_context_from_visible(
    &self,
    visible_right_content: &str,
    right_cursor_column: Option<usize>,
) {
    let left_inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
    let left_lines = self
        .left_display_lines(left_inner_width)
        .into_iter()
        .map(|line| line.text)
        .collect::<Vec<_>>();
    let right_lines = split_preserving_empty_lines(visible_right_content)
        .into_iter()
        .map(str::to_string)
        .collect::<Vec<_>>();
    let right_cursor = right_visual_cursor_position(&right_lines, right_cursor_column);

    *self.visual_context.borrow_mut() = VisualContext {
        left_lines,
        right_lines,
        right_cursor,
    };
}

fn refresh_left_visual_context(&self) {
    let left_inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
    self.visual_context.borrow_mut().left_lines = self
        .left_display_lines(left_inner_width)
        .into_iter()
        .map(|line| line.text)
        .collect();
}

fn start_visual_selection(&mut self, kind: VisualKind) {
    self.mode = UiMode::Command;
    self.pending = None;
    let anchor = self.focused_visual_position(kind);
    self.visual_selection = Some(VisualSelection {
        pane: self.focus,
        kind,
        anchor,
        cursor: anchor,
    });
}

fn handle_visual_key(&mut self, key: UiKey) -> Vec<UiAction> {
    match key {
        UiKey::Esc => {
            self.clear_visual_selection();
        }
        UiKey::Char('y') => {
            self.yank_visual_selection(false);
        }
        UiKey::Char('Y') => {
            self.yank_visual_selection(true);
        }
        UiKey::Char('v') => {
            self.toggle_visual_kind(VisualKind::Character);
        }
        UiKey::Char('V') => {
            self.toggle_visual_kind(VisualKind::Line);
        }
        UiKey::Char(CTRL_V_CHAR) => {
            self.toggle_visual_kind(VisualKind::Block);
        }
        UiKey::Char('h') | UiKey::Left => {
            self.move_visual_cursor(0, -1);
        }
        UiKey::Char('j') | UiKey::Down => {
            self.move_visual_cursor(1, 0);
        }
        UiKey::Char('k') | UiKey::Up => {
            self.move_visual_cursor(-1, 0);
        }
        UiKey::Char('l') | UiKey::Right => {
            self.move_visual_cursor(0, 1);
        }
        _ => {}
    }
    Vec::new()
}

fn toggle_visual_kind(&mut self, kind: VisualKind) {
    let Some(selection) = self.visual_selection.as_ref() else {
        self.start_visual_selection(kind);
        return;
    };
    if selection.kind == kind {
        self.clear_visual_selection();
        return;
    }
    if let Some(selection) = self.visual_selection.as_mut() {
        selection.kind = kind;
    }
    self.clamp_visual_selection();
}

fn focused_visual_position(&self, kind: VisualKind) -> VisualPosition {
    let context = self.visual_context.borrow();
    match self.focus {
        PaneFocus::Left => {
            let row = self
                .control_selected
                .min(context.left_lines.len().saturating_sub(1));
            VisualPosition { row, column: 0 }
        }
        PaneFocus::Right => clamp_visual_position(
            context.right_cursor,
            &context.right_lines,
            kind,
            usize::from(self.layout().right_width.saturating_sub(2).max(1)),
        ),
    }
}

fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
    let Some(selection) = self.visual_selection.as_ref() else {
        return;
    };
    let pane = selection.pane;
    let kind = selection.kind;
    let cursor = selection.cursor;
    let width = self.visual_pane_inner_width(pane);
    let lines = self.visual_lines_for_pane(pane);

    let row = apply_delta(cursor.row, row_delta).min(lines.len().saturating_sub(1));
    let column = apply_delta(cursor.column, column_delta);
    let cursor = clamp_visual_position(VisualPosition { row, column }, &lines, kind, width);

    if let Some(selection) = self.visual_selection.as_mut() {
        selection.cursor = cursor;
    }
}

fn clamp_visual_selection(&mut self) {
    let Some(selection) = self.visual_selection.as_ref() else {
        return;
    };
    let pane = selection.pane;
    let kind = selection.kind;
    let width = self.visual_pane_inner_width(pane);
    let lines = self.visual_lines_for_pane(pane);
    let anchor = clamp_visual_position(selection.anchor, &lines, kind, width);
    let cursor = clamp_visual_position(selection.cursor, &lines, kind, width);

    if let Some(selection) = self.visual_selection.as_mut() {
        selection.anchor = anchor;
        selection.cursor = cursor;
    }
}

fn yank_visual_selection(&mut self, force_linewise: bool) {
    let Some(mut selection) = self.visual_selection.clone() else {
        return;
    };
    if force_linewise {
        selection.kind = VisualKind::Line;
    }
    let Some(text) = self.selected_text(&selection) else {
        self.clear_visual_selection();
        return;
    };
    self.queue_clipboard(text);
    self.clear_visual_selection();
}

fn yank_focused_line(&mut self) {
    let Some(mut line) = self.focused_line_text() else {
        return;
    };
    line.push('\n');
    self.queue_clipboard(line);
}

fn selected_text(&self, selection: &VisualSelection) -> Option<String> {
    let lines = self.visual_lines_for_pane(selection.pane);
    if lines.is_empty() {
        return None;
    }
    let start_row = selection.anchor.row.min(selection.cursor.row);
    let end_row = selection
        .anchor
        .row
        .max(selection.cursor.row)
        .min(lines.len().saturating_sub(1));
    if start_row > end_row {
        return None;
    }

    match selection.kind {
        VisualKind::Line => {
            let mut text = lines[start_row..=end_row].join("\n");
            text.push('\n');
            Some(text)
        }
        VisualKind::Character | VisualKind::Block => {
            let mut selected = Vec::new();
            for (row, line) in lines.iter().enumerate().take(end_row + 1).skip(start_row) {
                let line_len = line.chars().count();
                let (start, end) =
                    visual_range_for_row(selection, row, line_len).unwrap_or((0, 0));
                selected.push(slice_chars(line, start, end));
            }
            Some(selected.join("\n"))
        }
    }
}

fn focused_line_text(&self) -> Option<String> {
    let context = self.visual_context.borrow();
    let lines = match self.focus {
        PaneFocus::Left => &context.left_lines,
        PaneFocus::Right => &context.right_lines,
    };
    if lines.is_empty() {
        return None;
    }
    let row = match self.focus {
        PaneFocus::Left => self.control_selected,
        PaneFocus::Right => context.right_cursor.row,
    }
    .min(lines.len().saturating_sub(1));
    lines.get(row).cloned()
}

fn visual_lines_for_pane(&self, pane: PaneFocus) -> Vec<String> {
    let context = self.visual_context.borrow();
    match pane {
        PaneFocus::Left => context.left_lines.clone(),
        PaneFocus::Right => context.right_lines.clone(),
    }
}

fn visual_pane_inner_width(&self, pane: PaneFocus) -> usize {
    let layout = self.layout();
    match pane {
        PaneFocus::Left => usize::from(layout.left_width.saturating_sub(2).max(1)),
        PaneFocus::Right => usize::from(layout.right_width.saturating_sub(2).max(1)),
    }
}

}

fn visual_cursor_screen_position(&self) -> Option<(u16, u16)> {
    let selection = self.visual_selection.as_ref()?;
    let context = self.visual_context.borrow();
    let layout = self.layout();
    match selection.pane {
        PaneFocus::Left if self.left_visible => {
            let row =
                2_u16.saturating_add(selection.cursor.row.min(usize::from(u16::MAX)) as u16);
            let column = 2_u16.saturating_add(
                selection
                    .cursor
                    .column
                    .min(usize::from(layout.left_width.saturating_sub(2).max(1)))
                    .min(usize::from(u16::MAX)) as u16,
            );
            Some((row, column))
        }
        PaneFocus::Right => {
            let inner_width = layout.right_width.saturating_sub(2).max(1);
            let rows_before = context
                .right_lines
                .iter()
                .take(selection.cursor.row)
                .map(|line| visual_rows(line, inner_width))
                .sum::<u16>();
            let column = selection.cursor.column.min(usize::from(u16::MAX)) as u16;
            let row = 2_u16
                .saturating_add(rows_before)
                .saturating_add(column / inner_width);
            let column = layout
                .left_width
                .saturating_add(2)
                .saturating_add(column % inner_width);
            Some((row, column))
        }
        PaneFocus::Left => None,
    }
}

