    if self.paste_mode {
        match byte {
            13 => {
                self.skip_next_paste_lf = true;
                return Some(TerminalAppInput::LineBreak);
            }
            10 if self.skip_next_paste_lf => {
                self.skip_next_paste_lf = false;
